import Foundation

// what this is for
// and what it is not

public struct P {}

// SPDX-License-Identifier: MIT
//! Inner doc at the top.

/** A block doc comment. */
pub const A: &str = "//";

/// One line of documentation.
pub fn hazards() -> usize {
    let raw_deep = r##"a "# inside // and /* here"##;
    let raw_star = r#"closing */ inside a raw string"#;
    let byte = b"// not a comment";
    let byte_raw = br#"// nor this"#;
    let slash = '/';
    let quote = '\'';
    let backslash = '\\';
    let nul = '\u{0}';
    let solidus = "\u{2F}\u{2F} escaped slashes";
    let ends_in_escape = "trailing \\";
    let lifetime: &'static str = "//";
    let nested = 1 /* outer /* inner */ still outer */ + 2;
    let empty = 3 /**/ + 4;
    let stars = 5 /***/ + 6;
    let joined = 7/*x*/+ 8;
    let negate = -/*x*/-9_i32;
    let cast = 10_i32 as/*x*/i32;
    let generic: Vec<Vec/*x*/<u8>> = Vec::new();
    let attr = ATTRIBUTED;
    raw_deep.len() + raw_star.len() + byte.len() + byte_raw.len() + solidus.len()
        + ends_in_escape.len() + lifetime.len() + generic.len() + attr.len()
        + usize::try_from(nested + empty + stars + joined + negate.abs() + cast).unwrap_or(0)
        + usize::from(slash == quote || backslash == nul)
}

#[doc = "// not a comment either"]
pub const ATTRIBUTED: &str = "/* nor this */";

macro_rules! holding {
    () => {
        "// inside a macro body"
    };
}

/// The macro's expansion, which is a string and not a comment.
pub fn expanded() -> &'static str {
    holding!()
}

